UPDATE "opencv_app"."paper_docs" SET "engine" = 2, "head_version" = 0, "snapshot_version" = 0, "first_page" = NULL, "snapshot" = jsonb_build_object('type', 'doc', 'attrs', jsonb_build_object('schema', 1, 'template', CASE WHEN "kind" = 'cv' THEN 'classic' ELSE 'letter' END, 'page', '{"size":"A4","orientation":"portrait","marginsMpt":{"top":72000,"right":72000,"bottom":72000,"left":72000}}'::jsonb), 'content', jsonb_build_array(jsonb_build_object('type', 'text_block', 'attrs', jsonb_build_object('id', CASE WHEN "kind" = 'cv' THEN 'paragraph-1' ELSE 'letter-1' END, 'kind', 'paragraph', 'list', NULL, 'level', 0, 'align', 'left', 'lineSpacing', NULL, 'keepWithNext', NULL))));
